blocos=[]; falantes=[]
for ad in ADS:
    C=ad['chunks']; assert len(C)==len(ad['pt']),(ad['n'],len(C),len(ad['pt']))
    falas=[]
    for c,p in zip(C,ad['pt']):
        t=c.get('ts') or ts(c['start'])
        falas.append({"falante":c['spk'],"ts":t,"en":c['en'],"pt":p})
        if c['spk'] not in falantes: falantes.append(c['spk'])
    prints=[]
    for s,sl,l in ad['prints']:
        assert re.fullmatch(r'[a-z0-9_]+',sl),sl
        arq=f"ad{ad['n']:02d}_{sl}_00-{s//60:02d}-{s%60:02d}.jpg"
        Image.open(f"{ad['W']}/full/{s:05d}.jpg").convert('RGB').save(f'VSL-Pipeline-ADS6/frames/{arq}','JPEG',quality=88)
        prints.append({"ts":ts(s*1000),"legenda":l,"arquivo":arq})
    dur=max(c.get('end',0) for c in C) if 'end' in C[0] else 106000
    blocos.append({"n":ad['n'],"titulo":ad['titulo'],"inicio":"0:00","fim":ts(dur),"falas":falas,"prints":prints})
